package com.aaliyun.leadnews.search.service;import com.aaliyun.leadnews.feign.article.ArticleInternalClient;import com.aaliyun.leadnews.model.foundation.PageResponse;import com.aaliyun.leadnews.model.search.ArticleSearchDocument;import org.springframework.stereotype.Service;@Service public class SearchRebuildService{private final ArticleInternalClient articles;private final ArticleIndexService index;public SearchRebuildService(ArticleInternalClient a,ArticleIndexService i){articles=a;index=i;}public long rebuild()throws Exception{index.clearForRebuild();long page=1,total=0;while(true){PageResponse<ArticleSearchDocument> p=articles.searchDocuments(page,100);index.bulk(p.records());total+=p.records().size();if(total>=p.total()||p.records().isEmpty())return total;page++;}}}
